import{_ as s,l as i,o as e,c as l,v as t,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"流处理与窗口","description":"","frontmatter":{"title":"流处理与窗口","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stream-windows.md","filePath":"cs/stream-windows.md","lastUpdated":1789023840000}'),h={name:"cs/stream-windows.md"};function m(_,a,f,u,A,E){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="流处理与窗口" tabindex="-1">流处理与窗口 <a class="header-anchor" href="#流处理与窗口" aria-label="Permalink to &quot;流处理与窗口&quot;">​</a></h1><div class="epigraph"><p>无界输入没有「作业结束」。窗口把时间切成可聚合的有限包；事件时间与处理时间不是同一根轴。</p><footer>—— 据 Akidau et al., The Dataflow Model, VLDB 2015；流系统窗口语义通识</footer></div><p><a href="/cs/spark-dag">上一课</a>的 DAG 假定有界输入。缺口是<strong>一直来的记录</strong>：计数、join、聚合必须说清窗口。本课钉窗口；乱序与 watermark 下一课。不把套接字 read 循环当流引擎。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>滚动、滑动、会话窗口给出不同的键。按处理时间切：简单，结果依赖调度。按事件时间切：可复现，但记录会迟到。缺口是先承认两根时钟，再谈引擎。与批：窗口聚合在有界数据上就是 GROUP BY 时间桶。</p><p><span class="marginnote">Dataflow 模型把事件时间、watermark、触发器分开。不要把「微批 1 秒」叫做事件时间正确。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>声明窗口（大小、滑动、会话间隔）与时间属性。输出：每个窗口一个结果，或更新修订。状态：按键存窗口聚合。与湖仓：结果表用表格式提交。与背压：网络课的应用背压在此变成算子队列。</p>',8)),(e(),n(p,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%5B%22%E4%BA%8B%E4%BB%B6%E6%97%B6%E9%97%B4%22%5D%20--%3E%20WIN%5B%22%E7%AA%97%E5%8F%A3%22%5D%0A%20%20PROC%5B%22%E5%A4%84%E7%90%86%E6%97%B6%E9%97%B4%22%5D%20--%3E%20WIN%0A%20%20WIN%20--%3E%20AGG%5B%22%E6%AF%8F%E7%AA%97%E8%81%9A%E5%90%88%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>窗口是把无限流变成无限多个有限关系的规则。滚动不重叠、滑动重叠、会话靠空闲间隔切开。状态按键存累加器，检查点要带走；TTL 驱逐老窗，否则内存线性涨——像 <a href="/cs/mvcc-gc">MVCC GC</a> 的水位。两流 join 必须在时间上对齐窗口，否则中间积爆炸。并行按键 shuffle 到工人，倾斜键让单窗状态爆。</p><p>微批（固定处理时间切）实现简单，不等于事件时间正确。输出可以一次关窗发射，或早期触发出近似值再修订。结果可落入 <a href="/cs/timeseries-db">时序库</a> 或湖仓表。与 SQL <code>OVER</code>：那边行集有界且不收缩；这里窗口才让聚合有结束。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Flink 算子清单。下一课迟到与 watermark：事件时间进度声明。恰好一次再下一课。不要把套接字循环当流引擎。</p><p>后课默认：流聚合必须声明窗口与时间域。没有窗口的「流 GROUP BY」没有指称上的结束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>流聚合必须声明窗口；事件时间与处理时间要分开。</li><li>会话与 join 把状态变成一等资源。</li><li>Watermark 与乱序下一课。</li><li>出处：Akidau et al., VLDB 2015；对照 SQL 窗口课。</li></ul>',8))])}const k=s(h,[["render",m]]);export{T as __pageData,k as default};
